"""
Diagnosis:
- World 1: Found best_score=0.9 in round 2, then wasted 2 more rounds exploring a low-scoring branch (0.1->0.4).
- World 2: Found best_score=0.9 only in round 4; wasted round 2 refining a dead-end (0.4->0.4).
- Root re-expansion in rounds 3+ keeps spawning new depth-1 nodes but doesn't help when we already have a high score.
- Algorithmic change: Add score-based stopping logic. If best_score is high (>= 0.85) AND the best remaining frontier node's score is low (<= 0.3), stop.
  Also, after finding a high score, prefer deepening promising branches (score >= 0.6) over re-expanding root.
  Add a "good enough" threshold: once best_score >= threshold AND all frontier nodes have low scores, stop.
  This reduces wasted probes while maintaining quality.
"""

import math

def decide(view):
    """
    Exploration policy with adaptive stopping and score-aware branching.

    Algorithm:
    1. Track explored depth-1 nodes from history to avoid redundant root expansions.
    2. Categorize frontier nodes into fresh_depth1, scored_frontier, unscored_frontier.
    3. Adaptive stopping: if best_score >= 0.85 AND best frontier score <= 0.3, stop.
    4. Priority ranking when not stopping:
       - If we already have a high best_score, prioritize deepening promising branches
         (score >= 0.6) over root expansion.
       - Otherwise, use standard priority: fresh depth-1 > root > scored >= best > unscored.
    5. Select up to max_parallelism unique node IDs.
    """
    frontier = view['frontier']
    history = view['history']
    best_score = view['best_score']
    rounds_used = view['rounds_used']
    max_parallelism = view['max_parallelism']

    max_rounds_limit = view.get('max_rounds', None)

    # Build dict of explored depth-1 node IDs from history (replaces set)
    # A depth-1 node is 'explored' if it has been expanded (has children in history)
    explored_depth1 = {}
    for node in history:
        nid = node['id']
        depth = node['depth']
        children = node['children_count']
        if depth == 1 and children > 0:
            explored_depth1[nid] = True

    # Also mark nodes in frontier that have children_count > 0 as explored
    for node in frontier:
        if node['depth'] == 1 and node['children_count'] > 0:
            explored_depth1[node['id']] = True

    # Categorize frontier nodes
    fresh_depth1 = []
    scored_frontier = []
    unscored_frontier = []
    root_node = None

    for node in frontier:
        nid = node['id']
        depth = node['depth']
        score = node['score']

        if depth == 0:
            root_node = node
        elif depth == 1:
            if nid in explored_depth1:
                if score is not None:
                    scored_frontier.append(node)
                else:
                    unscored_frontier.append(node)
            else:
                fresh_depth1.append(node)
        else:
            if score is not None:
                scored_frontier.append(node)
            else:
                unscored_frontier.append(node)

    # Stop if no frontier to expand
    if not frontier:
        return {'expand': [], 'stop': True}

    # Stop if max rounds reached
    if max_rounds_limit is not None and rounds_used >= max_rounds_limit:
        return {'expand': [], 'stop': True}

    # Adaptive stopping: if best_score is high enough and remaining frontier is weak, stop
    # This prevents wasting probes on low-potential branches after finding a good solution
    if best_score is not None and best_score >= 0.85:
        best_frontier_score = None
        for node in frontier:
            s = node['score']
            if s is not None:
                if best_frontier_score is None or s > best_frontier_score:
                    best_frontier_score = s
        # If best frontier node score is low (<= 0.3), remaining work is unlikely to help
        if best_frontier_score is not None and best_frontier_score <= 0.3:
            return {'expand': [], 'stop': True}

    # Build candidate list for expansion
    candidates = []

    # Determine if we have a high score already (enables prioritization of promising branches)
    has_high_score = best_score is not None and best_score >= 0.6

    # Priority 1: Fresh depth-1 branches (unexplored)
    # Sort by score descending; None treated as lowest score
    def fresh_key(n):
        s = n['score']
        return s if s is not None else -999.0
    fresh_depth1.sort(key=fresh_key, reverse=True)

    # If we already have a high score, we may not want to keep exploring fresh branches
    # unless they have promising scores. Take fresh nodes with score >= 0.3, or all if none qualify
    if has_high_score:
        promising_fresh = [n for n in fresh_depth1 if n['score'] is not None and n['score'] >= 0.3]
        if not promising_fresh:
            # Fall back to the best fresh node anyway
            promising_fresh = fresh_depth1[:1] if fresh_depth1 else []
        for node in promising_fresh[:max_parallelism]:
            candidates.append(node)
    else:
        # Standard: take all fresh depth-1 nodes up to parallelism limit
        for node in fresh_depth1[:max_parallelism]:
            candidates.append(node)

    # Priority 2: Root (for new attempts) - only if we haven't selected enough candidates
    if len(candidates) < max_parallelism and root_node is not None:
        candidates.append(root_node)

    # Priority 3: Scored frontier nodes with score >= best_score (refinement of promising paths)
    if len(candidates) < max_parallelism:
        def scored_key(n):
            s = n['score']
            return s if s is not None else -999.0
        scored_frontier.sort(key=scored_key, reverse=True)
        for node in scored_frontier[:max_parallelism]:
            s = node['score']
            if s is not None and s >= best_score:
                candidates.append(node)
                if len(candidates) >= max_parallelism:
                    break

    # Priority 4: Unsced frontier nodes (fallback)
    if len(candidates) < max_parallelism:
        unscored_frontier.sort(key=lambda n: n['depth'])
        for node in unscored_frontier[:max_parallelism]:
            candidates.append(node)
            if len(candidates) >= max_parallelism:
                break

    # Build result
    expand_ids = [node['id'] for node in candidates]

    # Stop if we have no candidates
    stop = len(candidates) == 0

    result = {'expand': expand_ids, 'stop': stop}

    # Add parallelism if more than one candidate
    if len(candidates) > 1:
        result['parallelism'] = len(candidates)

    return result
